const CACHE_NAME="speedtest-v3",urlsToCache=["/","/index.html","/style.css","/script.js","https://cdn.jsdelivr.net/npm/chart.js@4/dist/chart.umd.js","https://unpkg.com/web-vitals"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(urlsToCache)))}),self.addEventListener("fetch",e=>{e.respondWith(caches.match(e.request).then(t=>t||fetch(e.request)))});